import { useEffect, useState } from "react";
import { api } from "../api/manuscriptApi";
import { useParams, useNavigate } from "react-router-dom";

export default function ManuscriptForm({ method }) {
  const { id } = useParams();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    title: "",
    abstract: "",
    keywords: "",
    reference_list: "",
    cover_letter: "",
    manuscript_file: null,
    supplementary_materials: [],
    plagiarism_score: 0,
    author_id: "",
    journal_id: "",
    assigned_editor_id: "",
    status: "Submitted"
  });

  useEffect(() => {
    if (method === "edit") {
      api.get(`/${id}`).then((res) => {
        const m = res.data;
        setForm({
          ...m,
          keywords: m.keywords?.join(","),
          supplementary_materials: [] // files can't be prefilled
        });
      });
    }
  }, [id]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const fd = new FormData();

    // Append all form fields
    Object.entries(form).forEach(([k, v]) => {
      if (k === "manuscript_file" && v) {
        fd.append(k, v);
      } else if (k === "supplementary_materials" && v.length > 0) {
        Array.from(v).forEach(file => fd.append("supplementary_materials", file));
      } else {
        fd.append(k, v);
      }
    });

    try {
      if (method === "create") await api.post("/", fd);
      else await api.put(`/${id}`, fd);
      navigate("/journal/list");
    } catch (err) {
      console.error("Error submitting manuscript:", err);
      alert("Error submitting manuscript. Check console for details.");
    }
  };

  return (
    <div className="container mt-4">
      <h3>{method === "create" ? "Create Manuscript" : "Edit Manuscript"}</h3>
      <form onSubmit={handleSubmit} className="row g-3">
        <div className="col-12">
          <input
            className="form-control"
            placeholder="Title"
            value={form.title}
            onChange={e => setForm({ ...form, title: e.target.value })}
            required
          />
        </div>

        <div className="col-12">
          <textarea
            className="form-control"
            placeholder="Abstract"
            value={form.abstract}
            onChange={e => setForm({ ...form, abstract: e.target.value })}
            rows={4}
            required
          />
        </div>

        <div className="col-12">
          <textarea
            className="form-control"
            placeholder="Reference List"
            value={form.reference_list}
            onChange={e => setForm({ ...form, reference_list: e.target.value })}
            rows={4}
          />
        </div>

        <div className="col-12">
          <textarea
            className="form-control"
            placeholder="Cover Letter"
            value={form.cover_letter}
            onChange={e => setForm({ ...form, cover_letter: e.target.value })}
            rows={3}
          />
        </div>

        <div className="col-12">
          <input
            className="form-control"
            placeholder="Keywords (comma separated)"
            value={form.keywords}
            onChange={e => setForm({ ...form, keywords: e.target.value })}
          />
        </div>

        <div className="col-md-6">
          <input
            type="number"
            className="form-control"
            placeholder="Plagiarism Score"
            value={form.plagiarism_score}
            onChange={e => setForm({ ...form, plagiarism_score: e.target.value })}
          />
        </div>

        <div className="col-md-6">
          <input
            type="number"
            className="form-control"
            placeholder="Author ID"
            value={form.author_id}
            onChange={e => setForm({ ...form, author_id: e.target.value })}
          />
        </div>

        <div className="col-md-6">
          <input
            type="number"
            className="form-control"
            placeholder="Journal ID"
            value={form.journal_id}
            onChange={e => setForm({ ...form, journal_id: e.target.value })}
          />
        </div>

        <div className="col-md-6">
          <input
            type="number"
            className="form-control"
            placeholder="Assigned Editor ID"
            value={form.assigned_editor_id}
            onChange={e => setForm({ ...form, assigned_editor_id: e.target.value })}
          />
        </div>

        <div className="col-12">
          <input
            type="file"
            className="form-control"
            onChange={e => setForm({ ...form, manuscript_file: e.target.files[0] })}
            accept=".pdf,.doc,.docx"
          />
        </div>

        <div className="col-12">
          <input
            type="file"
            className="form-control"
            multiple
            onChange={e => setForm({ ...form, supplementary_materials: e.target.files })}
          />
        </div>

        <div className="col-12">
          <select
            className="form-control"
            value={form.status}
            onChange={(e) => setForm({ ...form, status: e.target.value })}
          >
            <option>Submitted</option>
            <option>Under Review</option>
            <option>Revision Requested</option>
            <option>Revision Submitted</option>
            <option>Accepted</option>
            <option>Published</option>
            <option>Desk Reject</option>
          </select>
        </div>

        <div className="col-12">
          <button className="btn btn-primary w-100">Save Manuscript</button>
        </div>
      </form>
    </div>
  );
}
